<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">&#x2190;</text><text class="nav-title">&#x5F55;&#x97F3;&#x673A;</text><text class="nav-icon"> </text></view></view><view class="content"><view class="recorder-panel"><view class="timer">{{ formattedTime }}</view><view class="wave-container"><view class="wave-bar" v-for="i in 12" :key="i" :style="{ height: recording ? (20 + Math.random()*60) + 'rpx' : '20rpx' }"></view></view><view class="controls"><view class="ctrl-btn record" :class="{active: recording}" @click="toggleRecord"><text>{{ recording ? '&#x25FC;' : '&#x25CF;' }}</text></view><view class="ctrl-btn" @click="stopRecord" :class="{disabled: !recording}"><text>&#x25FC;&#x25FC;</text></view></view></view><view class="recording-list" v-if="recordings.length"><text class="section-title">&#x5F55;&#x97F3;&#x5217;&#x8868;</text><view class="rec-item" v-for="(rec, idx) in recordings" :key="idx"><view class="rec-info"><text class="rec-name">{{ rec.name }}</text><text class="rec-duration">{{ rec.duration }}</text></view><view class="rec-actions"><text class="rec-btn" @click="playRec(idx)">&#x25B6;</text><text class="rec-btn delete" @click="deleteRec(idx)">&#x2715;</text></view></view></view></view></view></template><script setup>import { ref, computed, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const recording = ref(false)
const seconds = ref(0)
const recordings = ref([])
const recorderManager = uni.getRecorderManager()
const formattedTime = computed(function() { var m = Math.floor(seconds.value / 60); var s = seconds.value % 60; return (m < 10 ? "0" : "") + m + ":" + (s < 10 ? "0" : "") + s })
var timer = null
function goBack() { uni.navigateBack() }
function toggleRecord() { if (recording.value) { recorderManager.stop(); recording.value = false; clearInterval(timer); recordings.value.push({ name: "&#x5F55;&#x97F3; " + (recordings.value.length + 1), duration: formattedTime.value, time: Date.now() }) } else { recorderManager.start({ format: "mp3" }); recording.value = true; seconds.value = 0; timer = setInterval(function() { seconds.value++ }, 1000) } }
function stopRecord() { if (!recording.value) return; recorderManager.stop(); recording.value = false; clearInterval(timer); recordings.value.push({ name: "&#x5F55;&#x97F3; " + (recordings.value.length + 1), duration: formattedTime.value, time: Date.now() }) }
function playRec(idx) { var ctx = uni.createInnerAudioContext(); ctx.src = recordings.value[idx].path; ctx.play() }
function deleteRec(idx) { recordings.value.splice(idx, 1) }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#e11d48,#be123c);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:44rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.recorder-panel{background:#fff;border-radius:16rpx;padding:40rpx;text-align:center;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04);margin-bottom:24rpx}.timer{font-size:64rpx;font-weight:700;color:#e11d48;font-family:monospace;margin-bottom:32rpx}.wave-container{display:flex;align-items:center;justify-content:center;gap:8rpx;height:120rpx;margin-bottom:32rpx}.wave-bar{width:16rpx;background:linear-gradient(180deg,#e11d48,#f43f5e);border-radius:8rpx;transition:height .2s}.controls{display:flex;justify-content:center;gap:32rpx}.ctrl-btn{width:120rpx;height:120rpx;border-radius:50%;background:#f5f7fb;display:flex;align-items:center;justify-content:center;font-size:40rpx;color:#e11d48}.ctrl-btn.record{background:linear-gradient(135deg,#e11d48,#be123c)}.ctrl-btn.record text{color:#fff}.ctrl-btn.disabled{opacity:.4}.recording-list{background:#fff;border-radius:16rpx;padding:24rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04)}.section-title{font-size:28rpx;color:#333;font-weight:600;display:block;margin-bottom:16rpx}.rec-item{display:flex;justify-content:space-between;align-items:center;padding:16rpx 0;border-bottom:1rpx solid #f0f0f0}.rec-info{flex:1}.rec-name{font-size:28rpx;color:#333;display:block}.rec-duration{font-size:24rpx;color:#999}.rec-actions{display:flex;gap:16rpx}.rec-btn{width:64rpx;height:64rpx;border-radius:50%;background:#f5f7fb;display:flex;align-items:center;justify-content:center;font-size:28rpx;color:#e11d48}.rec-btn.delete{color:#999}</style>